// Minimal synthetic replica of expo-modules-core's compiled build output. The
// real package bridges into native via JSI; here the accessors return inert
// handles so Expo packages that call them at module load still bundle.
export function requireNativeModule(moduleName) {
  return globalThis.expo?.modules?.[moduleName] ?? null;
}
export function requireOptionalNativeModule(moduleName) {
  return globalThis.expo?.modules?.[moduleName] ?? null;
}
export function requireNativeViewManager(viewName) {
  return viewName;
}
export function requireNativeView(viewName) {
  return viewName;
}
export class NativeModule {}
export class SharedObject {}
export const EXPO_MODULES_CORE_OK = "EXPO_MODULES_CORE_OK";
